const j = $input.first().json;
const wf = (j.workflow && j.workflow.name) || 'unknown workflow';
const execId = (j.execution && j.execution.id) || null;
const execUrl = (j.execution && j.execution.url) || '';
let node = 'unknown node';
let message = 'unknown error';
try {
  const err = j.execution && j.execution.error;
  if (err) { node = (err.node && err.node.name) || node; message = err.message || message; }
} catch (e) {}
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = 'SCOUT ERROR in ' + esc(wf) + '\nnode: ' + esc(node) + '\nerror: ' + esc(String(message).slice(0, 500)) + (execUrl ? '\n' + esc(execUrl) : '');
return [{ json: { workflow: wf, node, message: String(message).slice(0, 1000), execution_id: execId, execution_url: execUrl, text } }];
